<?php
require_once 'auth_guard.php';
$user = mv_get_logged_in_user($conn);
if (!$user) { header('Location: account.html?login=required'); exit; }
$roleStmt=$conn->prepare("SELECT role FROM users WHERE user_id=?");
$roleStmt->bind_param("i",$user['user_id']); $roleStmt->execute();
$roleRow=$roleStmt->get_result()->fetch_assoc(); $roleStmt->close();
if (!$roleRow || $roleRow['role'] !== 'admin') { http_response_code(403); exit('403 Forbidden — administrator access only.'); }
$message='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  if (($_POST['action']??'')==='save_product') {
    $id=(int)($_POST['product_id']??0); $name=trim($_POST['product_name']??''); $brand=trim($_POST['brand_name']??''); $price=(float)($_POST['price']??0); $stock=(int)($_POST['stock_quantity']??0); $image=trim($_POST['image_url']??''); $ram=trim($_POST['ram']??''); $storage=trim($_POST['storage']??''); $sku=trim($_POST['sku']??''); $description=trim($_POST['description']??''); $os=trim($_POST['os']??''); $display=trim($_POST['display']??''); $camera=trim($_POST['camera']??''); $battery=trim($_POST['battery']??''); $processor=trim($_POST['processor']??''); $color=trim($_POST['color']??''); $warranty=trim($_POST['warranty']??'');
    if ($name===''||$brand===''||$price<=0||$stock<0||$sku==='') $message='Please provide valid product, brand, price, stock and SKU.';
    else {
      $conn->begin_transaction();
      try {
        $s=$conn->prepare("INSERT INTO brands(brand_name) VALUES(?) ON DUPLICATE KEY UPDATE brand_name=VALUES(brand_name)");$s->bind_param('s',$brand);$s->execute();$s->close();
        $s=$conn->prepare("SELECT brand_id FROM brands WHERE brand_name=?");$s->bind_param('s',$brand);$s->execute();$bid=(int)$s->get_result()->fetch_assoc()['brand_id'];$s->close();
        if($id>0){
          $s=$conn->prepare("UPDATE products SET product_name=?,brand_id=?,image_url=?,description=?,os=?,display=?,camera=?,battery=?,processor=? WHERE product_id=?");$s->bind_param('sisssssssi',$name,$bid,$image,$description,$os,$display,$camera,$battery,$processor,$id);$s->execute();$s->close();
          $s=$conn->prepare("SELECT variant_id FROM product_variants WHERE product_id=? ORDER BY variant_id LIMIT 1");$s->bind_param('i',$id);$s->execute();$v=$s->get_result()->fetch_assoc();$s->close();
          if($v){$vid=(int)$v['variant_id'];$s=$conn->prepare("UPDATE product_variants SET price=?,stock_quantity=?,ram=?,storage=?,sku=?,color=?,warranty=? WHERE variant_id=?");$s->bind_param('disssssi',$price,$stock,$ram,$storage,$sku,$color,$warranty,$vid);$s->execute();$s->close();}
          else {$s=$conn->prepare("INSERT INTO product_variants(product_id,ram,storage,price,stock_quantity,sku,color,warranty) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('issdisss',$id,$ram,$storage,$price,$stock,$sku,$color,$warranty);$s->execute();$s->close();}
        } else {
          $category='Smartphone';$status='active';$s=$conn->prepare("INSERT INTO products(brand_id,product_name,category,image_url,status,description,os,display,camera,battery,processor) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$s->bind_param('issssssssss',$bid,$name,$category,$image,$status,$description,$os,$display,$camera,$battery,$processor);$s->execute();$pid=$conn->insert_id;$s->close();
          $s=$conn->prepare("INSERT INTO product_variants(product_id,ram,storage,price,stock_quantity,sku,color,warranty) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param('issdisss',$pid,$ram,$storage,$price,$stock,$sku,$color,$warranty);$s->execute();$s->close();
        }
        $conn->commit();$message='Product saved.';
      } catch(Throwable $e){$conn->rollback();$message='Could not save product. Check that the SKU is unique.';}
    }
  } elseif(($_POST['action']??'')==='deactivate') {
    $id=(int)($_POST['product_id']??0);$s=$conn->prepare("UPDATE products SET status='inactive' WHERE product_id=?");$s->bind_param('i',$id);$s->execute();$s->close();$message='Product deactivated.';
  } elseif(($_POST['action']??'')==='order_status') {
    $id=(int)($_POST['order_id']??0);$status=$_POST['order_status']??'Pending';
    if(in_array($status,['Pending','Processing','Shipped','Delivered','Cancelled'],true)){$s=$conn->prepare("UPDATE orders SET order_status=? WHERE order_id=?");$s->bind_param('si',$status,$id);$s->execute();$s->close();$message='Order status updated.';}
  }
}
$products=$conn->query("SELECT p.product_id,p.product_name,p.status,b.brand_name,v.variant_id,v.price,v.stock_quantity,v.ram,v.storage,v.sku,p.display,p.camera,p.battery,p.processor FROM products p JOIN brands b ON b.brand_id=p.brand_id LEFT JOIN product_variants v ON v.product_id=p.product_id ORDER BY p.product_id DESC")->fetch_all(MYSQLI_ASSOC);
$orders=$conn->query("SELECT o.order_id,o.total_amount,o.order_status,o.payment_status,o.order_date,u.first_name,u.last_name,u.email FROM orders o JOIN users u ON u.user_id=o.user_id ORDER BY o.order_id DESC LIMIT 100")->fetch_all(MYSQLI_ASSOC);
$counts=$conn->query("SELECT (SELECT COUNT(*) FROM products WHERE status='active') products,(SELECT COUNT(*) FROM orders) orders,(SELECT COUNT(*) FROM product_variants WHERE stock_quantity<5) low_stock")->fetch_assoc();
$editProduct=null; if(isset($_GET['edit'])){$editId=(int)$_GET['edit'];$es=$conn->prepare("SELECT p.product_id,p.product_name,p.image_url,p.description,p.os,p.display,p.camera,p.battery,p.processor,b.brand_name,v.price,v.stock_quantity,v.ram,v.storage,v.sku,v.color,v.warranty FROM products p JOIN brands b ON b.brand_id=p.brand_id LEFT JOIN product_variants v ON v.product_id=p.product_id WHERE p.product_id=? ORDER BY v.variant_id LIMIT 1");$es->bind_param('i',$editId);$es->execute();$editProduct=$es->get_result()->fetch_assoc();$es->close();}
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MobiVibe Admin</title><link rel="stylesheet" href="style.css"><style>
.admin-wrap{max-width:1200px;margin:35px auto;padding:0 18px}.admin-top{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.admin-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px;margin:24px 0}.admin-stat,.admin-panel{background:#fff;border:1px solid #e6e8ef;border-radius:12px;padding:18px}.admin-stat strong{display:block;font-size:28px}.admin-panel{margin:20px 0;overflow-x:auto}.admin-panel h2{margin-top:0}.admin-table{width:100%;border-collapse:collapse;min-width:700px}.admin-table th,.admin-table td{text-align:left;padding:10px;border-bottom:1px solid #eee}.admin-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.admin-form input,.admin-form select{width:100%;padding:10px;border:1px solid #ccd0d8;border-radius:7px}.admin-message{padding:12px;background:#eef8ee;border-radius:8px}.inline-form{display:flex;gap:6px;align-items:center}.inline-form select{padding:7px}
</style></head><body><div class="admin-wrap"><div class="admin-top"><div><h1>MobiVibe Admin Dashboard</h1><p>Signed in as <?=h($user['first_name'].' '.$user['last_name'])?></p></div><a class="btn btn-secondary" href="index.html">View Store</a></div><?php if($message!==''):?><p class="admin-message"><?=h($message)?></p><?php endif;?>
<div class="admin-stats"><div class="admin-stat">Active Products<strong><?=h($counts['products'])?></strong></div><div class="admin-stat">Orders<strong><?=h($counts['orders'])?></strong></div><div class="admin-stat">Low Stock (&lt;5)<strong><?=h($counts['low_stock'])?></strong></div></div>
<section class="admin-panel"><h2><?= $editProduct ? 'Edit Product #'.h($editProduct['product_id']) : 'Add Product' ?></h2><form method="post" class="admin-form"><input type="hidden" name="action" value="save_product"><input type="hidden" name="product_id" value="<?=h($editProduct['product_id']??0)?>"><input name="product_name" placeholder="Product name" value="<?=h($editProduct['product_name']??'')?>" required><input name="brand_name" placeholder="Brand" value="<?=h($editProduct['brand_name']??'')?>" required><input name="price" type="number" min="0.01" step=".01" placeholder="Price (LKR)" value="<?=h($editProduct['price']??'')?>" required><input name="stock_quantity" type="number" min="0" placeholder="Stock quantity" value="<?=h($editProduct['stock_quantity']??'')?>" required><input name="ram" placeholder="RAM e.g. 8GB" value="<?=h($editProduct['ram']??'')?>"><input name="storage" placeholder="Storage e.g. 128GB" value="<?=h($editProduct['storage']??'')?>"><input name="display" placeholder="Display e.g. 6.7-inch AMOLED" value="<?=h($editProduct['display']??'')?>"><input name="camera" placeholder="Camera e.g. 50MP triple camera" value="<?=h($editProduct['camera']??'')?>"><input name="battery" placeholder="Battery e.g. 5000mAh" value="<?=h($editProduct['battery']??'')?>"><input name="processor" placeholder="Processor e.g. Snapdragon 8 Elite" value="<?=h($editProduct['processor']??'')?>"><input name="os" placeholder="Operating system e.g. Android 16" value="<?=h($editProduct['os']??'')?>"><input name="color" placeholder="Color" value="<?=h($editProduct['color']??'')?>"><input name="warranty" placeholder="Warranty e.g. Official 1 Year" value="<?=h($editProduct['warranty']??'')?>"><input name="description" placeholder="Product description" value="<?=h($editProduct['description']??'')?>"><input name="sku" placeholder="Unique SKU" value="<?=h($editProduct['sku']??'')?>" required><input name="image_url" placeholder="Image URL" value="<?=h($editProduct['image_url']??'')?>"><button class="btn btn-primary">Save Product</button><?php if($editProduct):?><a class="btn btn-secondary" href="admin.php">Cancel</a><?php endif;?></form></section>
<section class="admin-panel"><h2>Products & Inventory</h2><table class="admin-table"><thead><tr><th>ID</th><th>Product</th><th>Brand</th><th>Price (LKR)</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=h($p['product_id'])?></td><td><?=h($p['product_name'])?></td><td><?=h($p['brand_name'])?></td><td><?=h($p['price']??'—')?></td><td><?=h($p['stock_quantity']??'—')?></td><td><?=h($p['status'])?></td><td><a class="btn btn-secondary" href="admin.php?edit=<?=h($p['product_id'])?>">Edit</a> <?php if($p['status']==='active'):?><form method="post"><input type="hidden" name="action" value="deactivate"><input type="hidden" name="product_id" value="<?=h($p['product_id'])?>"><button class="btn btn-secondary">Deactivate</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section>
<section class="admin-panel"><h2>Customer Orders</h2><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=h($o['order_id'])?><br><small><?=h($o['order_date'])?></small></td><td><?=h($o['first_name'].' '.$o['last_name'])?><br><?=h($o['email'])?></td><td>Rs. <?=number_format((float)$o['total_amount'],2)?></td><td><?=h($o['payment_status'])?></td><td><?=h($o['order_status'])?></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="order_status"><input type="hidden" name="order_id" value="<?=h($o['order_id'])?>"><select name="order_status"><?php foreach(['Pending','Processing','Shipped','Delivered','Cancelled'] as $st):?><option <?= $o['order_status']===$st?'selected':''?>><?=h($st)?></option><?php endforeach;?></select><button class="btn btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></section></div></body></html>